WITH gaps AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY device ORDER BY started_at ASC, id ASC) > INTERVAL '30' DAY THEN 1 ELSE 0 END AS is_new_session FROM sessions), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY device ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT DATE_TRUNC('MONTH', started_at) AS activity_month, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS duration_min, ROUND(SUM(is_new_session) / NULLIF(COUNT(CASE WHEN country = 'DE' THEN 1 END), 0), 2) AS is_new_session_per_de, ROUND(AVG(is_new_session), 2) AS avg_is_new_session, COUNT(DISTINCT browser) AS distinct_browsers, COUNT(DISTINCT country) AS distinct_countries, COUNT(*) AS cnt FROM sessionized GROUP BY DATE_TRUNC('MONTH', started_at);
